-- Rollback 244: remove the ten inserted BECE beta questions; preserve remediation history.
PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS _expected_244 (question_id TEXT PRIMARY KEY, topic_id TEXT NOT NULL, subject_id TEXT NOT NULL, exam_type_id TEXT NOT NULL, question_text TEXT NOT NULL, question_type TEXT NOT NULL, options TEXT NOT NULL, correct_answer TEXT NOT NULL, explanation TEXT NOT NULL, difficulty TEXT NOT NULL, points INTEGER NOT NULL, marks INTEGER NOT NULL, time_limit INTEGER NOT NULL, command_word TEXT NOT NULL, assessment_objective TEXT NOT NULL);
DELETE FROM _expected_244;
INSERT INTO _expected_244(question_id,topic_id,subject_id,exam_type_id,question_text,question_type,options,correct_answer,explanation,difficulty,points,marks,time_limit,command_word,assessment_objective) VALUES
  ('q_bece_math_sets_b001_031','topic_bece_math_sets','subj_bece_math','exam_bece','If A ∩ B = A, what follows?','multiple_choice','["A. A and B are disjoint","B. B is empty","C. A ⊆ B","D. A has no B elements"]','C','If intersection leaves all of A unchanged, every member of A must already belong to B. Therefore the correct answer is C: A ⊆ B.','hard',1,1,90,'Deduce','AO3'),
  ('q_bece_math_sets_b001_032','topic_bece_math_sets','subj_bece_math','exam_bece','If A ∪ B = B, what follows?','multiple_choice','["A. B ⊆ A only","B. A ⊆ B","C. A and B are disjoint","D. B is empty"]','B','Adding A to B produces nothing new only when every member of A is already in B. Therefore the correct answer is B: A ⊆ B.','hard',1,1,90,'Deduce','AO3'),
  ('q_bece_math_sets_b001_033','topic_bece_math_sets','subj_bece_math','exam_bece','Eleven choose art only and five choose both art and music. How many choose art?','multiple_choice','["A. 11","B. 23","C. 16","D. 18"]','C','The art set contains the art-only region plus the overlap, so 11+5=16 learners choose art. Therefore the correct answer is C: 16.','medium',1,1,90,'Calculate','AO2'),
  ('q_bece_math_sets_b001_034','topic_bece_math_sets','subj_bece_math','exam_bece','A Venn diagram has 6 in A only, 3 in both and 8 in B only. Find n(A∪B).','multiple_choice','["A. 17","B. 9","C. 11","D. 14"]','A','The union contains all three separate regions inside the circles, so 6+3+8=17. Therefore the correct answer is A: 17.','medium',1,1,90,'Calculate','AO2'),
  ('q_bece_math_sets_b001_035','topic_bece_math_sets','subj_bece_math','exam_bece','If U={1,2,3,4,5,6} and A={2,4,6}, which option belongs to A′?','multiple_choice','["A. 2","B. 4","C. 6","D. 5"]','D','The complement is {1,3,5}. Among the choices, only 5 lies outside A while remaining inside U. Therefore the correct answer is D: 5.','medium',1,1,90,'Determine','AO2'),
  ('q_bece_math_sets_b001_036','topic_bece_math_sets','subj_bece_math','exam_bece','What happens when an entry is repeated in roster notation?','multiple_choice','["A. Cardinality always rises","B. The set becomes empty","C. It does not create a new set element","D. Letters become invalid"]','C','Membership matters, not repetition. Thus {1,1,2} represents the same set as {1,2}. Therefore the correct answer is C: It does not create a new set element.','medium',1,1,90,'Explain','AO2'),
  ('q_bece_math_sets_b001_037','topic_bece_math_sets','subj_bece_math','exam_bece','If n(A)=12, n(A∪B)=20 and n(A∩B)=5, find n(B).','multiple_choice','["A. 13","B. 3","C. 17","D. 37"]','A','Substitute into 20=12+n(B)−5. Rearranging gives n(B)=13. Therefore the correct answer is A: 13.','hard',1,1,90,'Calculate','AO3'),
  ('q_bece_math_sets_b001_038','topic_bece_math_sets','subj_bece_math','exam_bece','Of 35 people, 15 use bus only, 9 walk only and 6 do both. How many use neither?','multiple_choice','["A. 30","B. 11","C. 20","D. 5"]','D','The three inside regions total 15+9+6=30, leaving 35−30=5 outside both. Therefore the correct answer is D: 5.','hard',1,1,90,'Calculate','AO3'),
  ('q_bece_math_sets_b001_039','topic_bece_math_sets','subj_bece_math','exam_bece','What is the intersection of any set A with the empty set?','multiple_choice','["A. A","B. ∅","C. {0}","D. U"]','B','The empty set has no elements, so no element can be common to A and ∅; their intersection is empty. Therefore the correct answer is B: ∅.','easy',1,1,90,'Determine','AO1'),
  ('q_bece_math_sets_b001_040','topic_bece_math_sets','subj_bece_math','exam_bece','What is the union of any set A with the empty set?','multiple_choice','["A. ∅","B. A′","C. A","D. {A,∅}"]','C','Union collects members from either set. Since ∅ contributes none, the result contains exactly the members of A. Therefore the correct answer is C: A.','easy',1,1,90,'Determine','AO1');
CREATE TABLE IF NOT EXISTS _rollback_244_guard (valid INTEGER NOT NULL CHECK (valid = 1));
DELETE FROM _rollback_244_guard;
INSERT INTO _rollback_244_guard(valid) SELECT CASE WHEN
  NOT EXISTS (SELECT 1 FROM questions q JOIN _expected_244 e ON e.question_id=q.id WHERE NOT (q.id IS e.question_id AND q.topic_id IS e.topic_id AND q.subject_id IS e.subject_id AND q.exam_type_id IS e.exam_type_id AND q.question_text IS e.question_text AND q.question_type IS e.question_type AND q.options IS e.options AND q.correct_answer IS e.correct_answer AND q.explanation IS e.explanation AND q.difficulty IS e.difficulty AND q.points IS e.points AND q.marks IS e.marks AND q.time_limit IS e.time_limit AND q.command_word IS e.command_word AND q.assessment_objective IS e.assessment_objective))
  AND NOT EXISTS (SELECT 1 FROM question_content_releases r JOIN _expected_244 e ON e.question_id=r.question_id WHERE NOT (r.batch_id IS 'bece-math-sets-beta-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep practice content aligned to Ghana’s published NaCCA Common Core Programme curricula; not official WAEC or NaCCA examination material.' AND r.source_url IS 'https://nacca.gov.gh/common-core-programme-ccp/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1))
  AND NOT EXISTS (SELECT 1 FROM question_bank_remediation_log l JOIN _expected_244 e ON e.question_id=l.entity_id WHERE l.migration_id='244_bece_math_sets_beta_part_4' AND NOT (l.migration_id IS '244_bece_math_sets_beta_part_4' AND l.entity_type IS 'question' AND l.field_name IS 'insert' AND l.old_value IS NULL AND l.new_value IS 'bece-math-sets-beta-001'))
  AND (((SELECT COUNT(*) FROM questions q JOIN _expected_244 e ON e.question_id=q.id WHERE q.id IS e.question_id AND q.topic_id IS e.topic_id AND q.subject_id IS e.subject_id AND q.exam_type_id IS e.exam_type_id AND q.question_text IS e.question_text AND q.question_type IS e.question_type AND q.options IS e.options AND q.correct_answer IS e.correct_answer AND q.explanation IS e.explanation AND q.difficulty IS e.difficulty AND q.points IS e.points AND q.marks IS e.marks AND q.time_limit IS e.time_limit AND q.command_word IS e.command_word AND q.assessment_objective IS e.assessment_objective)=10 AND (SELECT COUNT(*) FROM question_content_releases r JOIN _expected_244 e ON e.question_id=r.question_id WHERE r.batch_id IS 'bece-math-sets-beta-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep practice content aligned to Ghana’s published NaCCA Common Core Programme curricula; not official WAEC or NaCCA examination material.' AND r.source_url IS 'https://nacca.gov.gh/common-core-programme-ccp/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)=10 AND (SELECT COUNT(*) FROM question_bank_remediation_log l JOIN _expected_244 e ON e.question_id=l.entity_id WHERE l.migration_id IS '244_bece_math_sets_beta_part_4' AND l.entity_type IS 'question' AND l.field_name IS 'insert' AND l.old_value IS NULL AND l.new_value IS 'bece-math-sets-beta-001')=10)
    OR ((SELECT COUNT(*) FROM questions q JOIN _expected_244 e ON e.question_id=q.id)=0 AND (SELECT COUNT(*) FROM question_content_releases r JOIN _expected_244 e ON e.question_id=r.question_id)=0 AND (SELECT COUNT(*) FROM question_bank_remediation_log l JOIN _expected_244 e ON e.question_id=l.entity_id WHERE l.migration_id='244_bece_math_sets_beta_part_4') IN (0,10)))
THEN 1 ELSE 0 END;
DELETE FROM questions WHERE id IN (SELECT question_id FROM _expected_244);
INSERT INTO _rollback_244_guard(valid) SELECT CASE WHEN (SELECT COUNT(*) FROM questions q JOIN _expected_244 e ON e.question_id=q.id)=0 AND (SELECT COUNT(*) FROM question_content_releases r JOIN _expected_244 e ON e.question_id=r.question_id)=0 THEN 1 ELSE 0 END;
DROP TABLE _expected_244;
DROP TABLE _rollback_244_guard;
